-- Brings the topic OBJECTS ("Các đồ vật") back after V34 removed it, with its 98 words (same rows as V16, the Vietnamese
-- names of V16 section 3, and the "VI + EN only" language modes of V20). Its questions are generated by the repeatable
-- R__zz_templates.sql (WHAT_IS_THIS), which re-runs because its text changed. TOYS stays removed.
-- Idempotent: on a database that still has the topic or the words nothing is duplicated.

INSERT INTO topics (code, name, name_vi, slug, description, description_vi, min_age, max_age, display_order, is_active, supported_modes)
VALUES
    ('OBJECTS', 'Objects', 'Các đồ vật', 'objects', 'Things around us', 'Đồ vật quanh bé', 1, 5, 6, TRUE, ARRAY['VI', 'EN']::VARCHAR(20)[])
ON CONFLICT (code) DO UPDATE SET is_active = TRUE, updated_at = now();

